//
// Mapa de colisao 2D da ilha, em coordenadas LOCAIS do modelo (antes de
// aplicar posicao/escala da ilha no main.cpp).
//   - kIslandWalkable: 1 = pode pisar, 0 = bloqueado (mar, paredes do castelo,
//                      torres, casas, rochas, cais, cercas, moinho). Ja inclui uma folga
//                      para a camera nao encostar/atravessar as superficies.
//                      (Versao SEM arvores e SEM barco: essas areas agora sao livres.)
//   - kIslandGroundMm: altura do terreno em milimetros (unidades locais x 1000).
// ============================================================
