// Converte posicao da CENA (mundo) para celula da grade. Retorna false se fora.
static inline bool island_cell_from_scene(
    float scene_x, float scene_z,
    float island_x, float island_z, float island_scale,
    int &cell_x, int &cell_z)
{
    const float local_x = (scene_x - island_x) / island_scale;
    const float local_z = (scene_z - island_z) / island_scale;

    cell_x = static_cast<int>(std::floor((local_x - kIslandGridX0) / kIslandGridCell));
    cell_z = static_cast<int>(std::floor((local_z - kIslandGridZ0) / kIslandGridCell));

    return cell_x >= 0 && cell_x < kIslandGridNX &&
           cell_z >= 0 && cell_z < kIslandGridNZ;
}

// true se a posicao (x, z) da cena e um lugar onde a pessoa pode ficar em pe.
static inline bool island_is_walkable(
    float scene_x, float scene_z,
    float island_x, float island_z, float island_scale)
{
    int cx = 0, cz = 0;

    if (!island_cell_from_scene(scene_x, scene_z, island_x, island_z, island_scale, cx, cz))
        return false;

    return kIslandWalkable[cz * kIslandGridNX + cx] != 0;
}

// Altura Y do chao (em unidades da CENA) com interpolacao bilinear.
